sys_ui_action.script:
/**
 * UI Action: Create Payment (Selected Charge Lines)
 * Table: x_2223823_apollo_0_charge_line
 * Action Name: apollo_chargeline_create_payment
 * List Banner Button: true
 * List Bottom Button: true
 * List Choice: true
 * Client: true
 * Onclick: apolloCreatePaymentSelected()
 * Condition: (parent && parent.total_balance > 0) || current.total_balance > 0 || current.status != 'paid'
 */

// ==============================================================================
// CLIENT-SIDE SCRIPT: Runs in browser when cashier clicks "Create Payment"
// ==============================================================================
function apolloCreatePaymentSelected() {
    var checkedLines = g_list.getChecked();
    if (!checkedLines || checkedLines.length === 0) {
        alert('Please select at least one unpaid charge line using the checkboxes.');
        return false;
    }

    var parentInvoiceId = '';
    if (typeof g_form !== 'undefined' && g_form.getTableName() === 'x_2223823_apollo_0_invoice') {
        parentInvoiceId = g_form.getUniqueValue();
    }

    // Call server-side Script Include to process payment securely
    var ga = new GlideAjax('x_2223823_apollo_0.ApolloPaymentUtils');
    ga.addParam('sysparm_name', 'ajaxCreatePaymentForChargeLines');
    ga.addParam('sysparm_lines', checkedLines);
    if (parentInvoiceId) {
        ga.addParam('sysparm_invoice_id', parentInvoiceId);
    }

    ga.getXMLAnswer(function(answer) {
        try {
            var res = JSON.parse(answer);
            if (res.success) {
                // Redirect cashier directly to the newly generated Payment record
                window.location.href = 'x_2223823_apollo_0_payment.do?sys_id=' + res.payment_id;
            } else {
                alert(res.message);
            }
        } catch (e) {
            alert('Payment processing response error: ' + answer);
        }
    });
}
